import{_ as e,o as t,c as d,ag as n}from"./chunks/framework.Dx86EdC1.js";const g=JSON.parse('{"title":"Pengaturan Situs & TTE","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/pengaturan.md","filePath":"panduan-pengguna/pengaturan.md","lastUpdated":1791382762000}'),r={name:"panduan-pengguna/pengaturan.md"};function i(o,a,s,l,u,p){return t(),d("div",null,[...a[0]||(a[0]=[n('<h1 id="pengaturan-situs-tte" tabindex="-1">Pengaturan Situs &amp; TTE <a class="header-anchor" href="#pengaturan-situs-tte" aria-label="Permalink to &quot;Pengaturan Situs &amp; TTE&quot;">​</a></h1><h2 id="pengaturan-situs-admin-settings" tabindex="-1">Pengaturan Situs (<code>/admin/settings</code>) <a class="header-anchor" href="#pengaturan-situs-admin-settings" aria-label="Permalink to &quot;Pengaturan Situs (`/admin/settings`)&quot;">​</a></h2><p>Mengelola identitas desa dan parameter portal (tersimpan di tabel <code>settings</code> per kunci + grup).</p><h3 id="grup-desa-village" tabindex="-1">Grup: Desa (<code>village</code>) <a class="header-anchor" href="#grup-desa-village" aria-label="Permalink to &quot;Grup: Desa (`village`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kunci</th><th>Fungsi</th></tr></thead><tbody><tr><td><code>village_name</code></td><td>Nama desa — tampil di portal, kop surat, PDF</td></tr><tr><td><code>village_code</code></td><td>Kode desa (untuk nomor surat)</td></tr><tr><td><code>subdistrict_name</code>, <code>district_name</code>, <code>province_name</code></td><td>Nama kecamatan/kabupaten/provinsi</td></tr><tr><td><code>village_address</code>, <code>postal_code</code></td><td>Alamat &amp; kode pos</td></tr><tr><td><code>village_phone</code>, <code>village_email</code></td><td>Kontak</td></tr></tbody></table><h3 id="grup-umum-general" tabindex="-1">Grup: Umum (<code>general</code>) <a class="header-anchor" href="#grup-umum-general" aria-label="Permalink to &quot;Grup: Umum (`general`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kunci</th><th>Fungsi</th></tr></thead><tbody><tr><td><code>app_title</code>, <code>app_tagline</code></td><td>Judul &amp; tagline situs publik</td></tr><tr><td><code>timezone</code></td><td>Zona waktu wilayah desa (WIB/WITA/WIT)</td></tr><tr><td><code>village_logo</code></td><td>Logo resmi desa — ditampilkan pada header portal publik, kartu profil landing page, footer website, KOP surat resmi (PDF &amp; pratinjau), sidebar admin, dan halaman login</td></tr></tbody></table><h3 id="grup-tema-theme" tabindex="-1">Grup: Tema (<code>theme</code>) <a class="header-anchor" href="#grup-tema-theme" aria-label="Permalink to &quot;Grup: Tema (`theme`)&quot;">​</a></h3><p><code>active_theme</code> — tema publik aktif. Dijelaskan di <a href="/panduan-pengguna/menu-tema.html">Menu &amp; Tema</a>.</p><h2 id="pengaturan-tte-admin-tte-settings" tabindex="-1">Pengaturan TTE (<code>/admin/tte-settings</code>) <a class="header-anchor" href="#pengaturan-tte-admin-tte-settings" aria-label="Permalink to &quot;Pengaturan TTE (`/admin/tte-settings`)&quot;">​</a></h2><p>Konfigurasi <strong>Tanda Tangan Elektronik tersertifikasi (PSrE/BSrE BSSN)</strong> untuk pengesahan surat Kepala Desa.</p><table tabindex="0"><thead><tr><th>Field</th><th>Sumber</th></tr></thead><tbody><tr><td>Provider</td><td><code>TTE_DEFAULT_PROVIDER</code> (default <code>bsre_bssn</code>)</td></tr><tr><td>Endpoint &amp; API key</td><td><code>TTE_BSRE_URL</code>, <code>TTE_BSRE_API_KEY</code></td></tr><tr><td>Client ID &amp; passphrase</td><td><code>TTE_BSRE_CLIENT_ID</code>, <code>TTE_BSRE_PASSPHRASE</code></td></tr><tr><td>Mode sandbox</td><td><code>TTE_BSRE_SANDBOX</code></td></tr><tr><td>TSA URL</td><td><code>TTE_BSRE_TSA_URL</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Batasan Wewenang TTE</p><p>Kewenangan TTE dokumen kependudukan negara (KK nasional) ada pada <strong>Kadisdukcapil via SIAK Terpusat</strong> (Permendagri 109/2019). TTE/QR di SiDesa hanya <strong>pengesahan Kepala Desa atas kebenaran salinan data desa</strong> — bukan pengganti dokumen resmi negara.</p></div><p>Ganti nilai demo dengan kredensial PSrE resmi sebelum produksi. Detail variabel: <a href="/panduan-pengembang/konfigurasi.html#tanda-tangan-elektronik-tte-bsre-bssn">Konfigurasi Environment</a>.</p><h2 id="profil-kata-sandi-sendiri" tabindex="-1">Profil &amp; Kata Sandi Sendiri <a class="header-anchor" href="#profil-kata-sandi-sendiri" aria-label="Permalink to &quot;Profil &amp; Kata Sandi Sendiri&quot;">​</a></h2><p>Semua pengguna (termasuk warga) dapat mengelola data diri di <code>/profile</code>:</p><ul><li>Ubah nama &amp; informasi kontak.</li><li>Ganti kata sandi (password lama wajib diisi).</li></ul>',17)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
